132	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
133	        Integer number = next == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
134	        RollupService.Snapshot before = rollup.snapshot(sheetId);
135	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
