214	export class PersonClaims {
215	  private readonly http = inject(HttpClient);
216	  private readonly session = inject(Session);
217	
218	  readonly personId = input.required<number>();
219	  readonly personName = input.required<string>();
220	  readonly claims = input.required<Claim[]>();
221	  /** The person's grades: the one in force on a claim's date, at its rate then, gives what the claim has due. */
222	  readonly grades = input.required<DatedGrade[]>();
223	  /** The sheet's rates. */
224	  readonly rates = input.required<Rate[]>();
225	  /** The sheet's floor in whole cents: the least a claim's live due can be. */
226	  readonly floor = input.required<number>();
227	  /** The sheet's terms: the days after its date a claim is due by. */
228	  readonly terms = input.required<number>();
229	  /** The sheet's late percent: what an overdue claim gains of its figure for every full 30 days. */
230	  readonly latePct = input.required<string>();
231	  /** The sheet's policy date (blank: its today): a claim dated before it rounds half up, else half to even. */
232	  readonly policyDate = input.required<string>();
233	  /** The sheet's periods. */
234	  readonly periods = input.required<Period[]>();
235	  readonly saved = output<Claim>();
236	
237	  protected readonly amountInput = signal('');
238	  protected readonly dateInput = signal('');
239	  protected readonly noteInput = signal('');
240	  protected readonly correctsInput = signal('');
241	  protected readonly editingId = signal<number | null>(null);
242	  protected readonly error = signal<string | null>(null);
243	  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
244	  private submitting = false;
245	  /** The error of each claim's last refused status change, by claim id. */
246	  protected readonly actionErrors = signal<ReadonlyMap<number, string>>(new Map());
247	
248	  /** A stated claim shows the figure bound by the last statement, a settled claim the due fixed
249	   *  when it was settled; any other claim's due is live, at the rate for the person's grade in
250	   *  force on the claim's date (the grade in force then), never below the sheet's floor. An overdue claim's late charge is
251	   *  added on top. */
252	  protected dueOf(c: Claim): string {
253	    const late: Lateness = {
254	      latePct: this.latePct(),
255	      terms: this.terms(),
256	      today: this.session.today(),
257	      policyDate: this.policyDate(),
258	    };
259	    const roundOn = roundingDate(c, this.claims());
260	    return dueText(chargedDueCents(c, this.rates(), gradeOn(this.grades(), c.date), this.floor(), late, roundOn));
261	  }
262	
263	  protected dueByOf(c: Claim): string {
264	    return dueBy(c, this.terms());
265	  }
266	
267	  protected overdueOf(c: Claim): boolean {
268	    return overdue(c, this.terms(), this.session.today());
269	  }
270	
271	  /** The name of the period whose dates contain the claim's date; blank when none does. */
272	  protected periodOf(c: Claim): string {
273	    return periodOn(this.periods(), c.date)?.name ?? '';
274	  }
275	
276	  protected edit(c: Claim): void {
277	    this.clearActionError(c.id);
278	    if (inClosedPeriod(this.periods(), c.date)) {
279	      this.actionErrors.update((m) => new Map(m).set(c.id, CLOSED));
280	      return;
281	    }
282	    if (c.status !== 'DRAFT') {
283	      this.actionErrors.update((m) => new Map(m).set(c.id, `A ${c.status} claim cannot be edited.`));
284	      return;
285	    }
286	    this.editingId.set(c.id);
287	    this.amountInput.set(c.amount);
288	    this.dateInput.set(c.date);
289	    this.noteInput.set(c.note);
290	    this.correctsInput.set(c.corrects === null ? '' : String(c.corrects));
291	    this.error.set(null);
292	  }
293	
294	  protected reset(): void {
295	    this.editingId.set(null);
296	    this.amountInput.set('');
297	    this.dateInput.set('');
298	    this.noteInput.set('');
299	    this.correctsInput.set('');
300	    this.error.set(null);
301	  }
302	
303	  private clearActionError(id: number): void {
304	    this.actionErrors.update((m) => {
305	      if (!m.has(id)) return m;
306	      const next = new Map(m);
307	      next.delete(id);
308	      return next;
309	    });
310	  }
311	
312	  /** Move a claim to its next status; the server refuses a move its status does not allow. */
313	  protected async act(c: Claim, action: ClaimAction): Promise<void> {
314	    this.clearActionError(c.id);
315	    const sheet = this.session.sheet();
316	    try {
317	      const claim = await firstValueFrom(
318	        this.http.post<Claim>(`/api/claims/${action}`, { sheet, user: this.session.user(), id: c.id }),
319	      );
320	      if (this.session.sheet() !== sheet) return;
321	      this.saved.emit(claim);
322	    } catch (e) {
323	      if (this.session.sheet() !== sheet) return;
324	      const err =
325	        e instanceof HttpErrorResponse && e.status === 403
326	          ? c.openedBy === this.session.user()
327	            ? 'The user who opened a claim cannot settle it.'
328	            : 'A clerk cannot settle a claim whose due is above the clerk limit.'
329	          : e instanceof HttpErrorResponse && e.status === 423
330	            ? CLOSED
331	            : `A ${c.status} claim cannot be ${PAST[action]}.`;
332	      this.actionErrors.update((m) => new Map(m).set(c.id, err));
333	    }
334	  }
335	
336	  /** Whether a claim number names a SETTLED claim of this person, as a correction must. */
337	  private correctable(corrects: string): boolean {
338	    return NUMBER.test(corrects) && this.claims().some((c) => c.number === Number(corrects) && c.status === 'SETTLED');
339	  }
340	
341	  protected async save(event: Event): Promise<void> {
342	    event.preventDefault();
343	    if (this.submitting) return;
344	    this.error.set(null);
345	    const sheet = this.session.sheet();
346	    const amount = this.amountInput().trim();
347	    const date = this.dateInput().trim();
348	    const corrects = this.correctsInput().trim();
349	    if (!SIGNED_AMOUNT.test(amount)) {
350	      this.error.set('Enter an amount with up to two decimals (below zero only for a correction).');
351	      return;
352	    }
353	    const correction = cents(amount) < 0;
354	    if (correction && !this.correctable(corrects)) {
355	      this.error.set(UNCORRECTABLE);
356	      return;
357	    }
358	    if (date !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
359	      this.error.set('Enter a date, or leave it blank for the sheet\'s today.');
360	      return;
361	    }
362	    const id = this.editingId();
363	    const body = { sheet, user: this.session.user(), amount, date: date || null, note: this.noteInput().trim(),
364	      corrects: correction ? Number(corrects) : null };
365	    this.submitting = true;
366	    try {
367	      const claim =
368	        id === null
369	          ? await firstValueFrom(this.http.post<Claim>('/api/claims/add', { ...body, personId: this.personId() }))
370	          : await firstValueFrom(this.http.post<Claim>('/api/claims/update', { ...body, id }));
371	      if (this.session.sheet() !== sheet) return;
372	      this.saved.emit(claim);
373	      this.reset();
374	    } catch (e) {
375	      this.error.set(
376	        e instanceof HttpErrorResponse && e.status === 423
377	          ? CLOSED
378	          : e instanceof HttpErrorResponse && e.status === 422
379	            ? 'A claim cannot be dated after its person\'s retirement date.'
380	          : e instanceof HttpErrorResponse && e.status === 400 && correction
381	            ? UNCORRECTABLE
382	          : e instanceof HttpErrorResponse && e.status === 409
383	            ? 'Only a DRAFT claim can be edited.'
384	            : id === null
385	              ? 'Could not add this claim.'
386	              : 'Could not save this claim.',
387	      );
388	    } finally {
389	      this.submitting = false;
390	    }
391	  }
392	}
